package org.jarvisassistant.app;
import android.app.*;
import android.hardware.biometrics.*;
import android.media.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.nio.*;
import java.util.*;

/** Owner-only inbox. Ciphertext cannot be decrypted using the public visitor write path. */
public final class PetMessagesActivity extends Activity {
    private LinearLayout body;private TextView status;private PetMessageStore store;private CancellationSignal cancellation;private final ArrayList<PetMessageStore.Note> opened=new ArrayList<>();private PetNoteAudio playback;private boolean active,authenticated,authenticating,pendingRead;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);LinearLayout root=NativeStyle.surface(this);root.addView(NativeStyle.toolbar(this,"Private messages","Only on this phone",this::finish));ScrollView scroll=new ScrollView(this);body=NativeStyle.column(this);int p=NativeStyle.dp(this,22);body.setPadding(p,p,p,p);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));playback=new PetNoteAudio(this,value->android.widget.Toast.makeText(this,value,android.widget.Toast.LENGTH_SHORT).show());status=NativeStyle.text(this,"Authenticate to open your messages.",14,NativeStyle.MUTED);body.addView(status);NativeStyle.gap(body,20);body.addView(NativeStyle.action(this,"Unlock messages","lock",true,this::authenticate));try{store=new PetMessageStore(this,getIntent().getStringExtra("origin"));}catch(Exception error){status.setText("Connect this phone to a JARVIS workspace first.");}}
    private void authenticate(){if(store==null||!active||authenticating)return;authenticating=true;cancellation=new CancellationSignal();BiometricPrompt.Builder builder=new BiometricPrompt.Builder(this).setTitle("Open private JARVIS messages").setSubtitle("Use your Android screen lock or fingerprint");if(Build.VERSION.SDK_INT>=30)builder.setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL);else if(Build.VERSION.SDK_INT>=29)builder.setDeviceCredentialAllowed(true);else builder.setNegativeButton("Cancel",getMainExecutor(),(dialog,which)->cancellation.cancel());builder.build().authenticate(cancellation,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult result){authenticating=false;if(active){authenticated=true;render();}else pendingRead=true;}@Override public void onAuthenticationError(int code,CharSequence message){authenticating=false;if(active)locked();}});}
    private void clear(){stopPlayback();for(PetMessageStore.Note note:opened)note.close();opened.clear();body.removeAllViews();}
    private void render(){clear();File[] files=store.files();body.addView(NativeStyle.title(this,files.length==0?"All quiet here.":"Messages left for you",23));NativeStyle.gap(body,20);for(File file:files)try{String id=file.getName().replace(".note","");PetMessageStore.Note note=store.read(id);opened.add(note);LinearLayout card=NativeStyle.card(this);card.addView(NativeStyle.text(this,android.text.format.DateFormat.format("EEE d MMM · HH:mm",new Date(note.created)).toString(),12,NativeStyle.MUTED));NativeStyle.gap(card,12);if(!note.text.isEmpty())card.addView(NativeStyle.text(this,note.text,17,NativeStyle.TEXT));if(note.pcm.length>0){NativeStyle.gap(card,12);card.addView(NativeStyle.action(this,"Play · "+note.pcm.length/32000+" seconds","play",false,()->play(note.pcm)));}NativeStyle.gap(card,12);card.addView(NativeStyle.action(this,"Delete message","close",false,()->new AlertDialog.Builder(this).setTitle("Delete this message?").setMessage("This removes its local encrypted copy.").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->{try{store.delete(id);render();}catch(Exception error){authenticated=false;clear();body.addView(NativeStyle.action(this,"Authenticate again to delete","lock",true,this::authenticate));}}).show()));body.addView(card);NativeStyle.gap(body,14);}catch(Exception error){body.addView(NativeStyle.text(this,"Authenticate again to read more messages.",14,NativeStyle.MUTED));body.addView(NativeStyle.action(this,"Unlock messages","lock",true,this::authenticate));break;}}
    private void play(byte[] pcm){if(active&&authenticated)playback.play(pcm);}
    private void stopPlayback(){if(playback!=null)playback.close();}
    private void locked(){clear();if(store==null){body.addView(NativeStyle.text(this,"Connect this phone to a JARVIS workspace first.",14,NativeStyle.MUTED));return;}body.addView(NativeStyle.text(this,"Messages stay locked until you authenticate.",14,NativeStyle.MUTED));NativeStyle.gap(body,18);body.addView(NativeStyle.action(this,"Unlock messages","lock",true,this::authenticate));}
    @Override protected void onResume(){super.onResume();active=true;if(pendingRead){pendingRead=false;authenticated=true;render();}else if(!authenticated&&!authenticating)locked();}
    @Override protected void onPause(){active=false;authenticated=false;if(!authenticating&&cancellation!=null)cancellation.cancel();clear();super.onPause();}
    @Override protected void onDestroy(){if(cancellation!=null)cancellation.cancel();clear();super.onDestroy();}
}
